head.script:
scwin.__getJq = function(q) {
	var j = $(q); if (j.length) return j;
	var P = 'mf_', t = q.trim(), r = t.slice(1);
	if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
	return $(t.slice(0, 1) + r);
};
scwin.trigger4_onclick = function(e) {
	treeview1.spanNode({
		index: 2
	});
};
scwin.trigger3_onclick = function(e) {
	treeview1.spanNode({
		depth: 2
	});
};
scwin.trigger6_onclick = function(e) {
	treeview1.spanNode({
		index: 1,
		applyChildNodes: true
	}, true);
};
scwin.trigger7_onclick = function(e) {
	treeview1.spanNode({
		depth: 2
	}, false);
};
scwin.trigger8_onclick = function(e) {
	treeview1.spanNode({
		depth: 2
	}, true);
};
scwin.isClosed = function(id) {
	return scwin.__getJq("#" + id).hasClass('w2treeview_close_child');
};
scwin.onpageload = function() {
	var data = [
		{"value": "a1", "label": "a1", "depth": "1"},
		{"value": "a1-1", "label": "a1-1", "depth": "2"},
		{"value": "a1-1-1", "label": "a1-1-1", "depth": "3"},
		{"value": "a1-1-2", "label": "a1-1-2", "depth": "3"},
		{"value": "a1-1-3", "label": "a1-1-3", "depth": "3"},
		{"value": "a1-2", "label": "a1-2", "depth": "2"},
		{"value": "a1-2-1", "label": "a1-2-1", "depth": "3"},
		{"value": "a1-2-2", "label": "a1-2-2", "depth": "3"},
		{"value": "a1-2-3", "label": "a1-2-3", "depth": "3"},
		{"value": "a1-3", "label": "a1-3", "depth": "2"},
		{"value": "a1-3-1", "label": "a1-3-1", "depth": "3"},
		{"value": "a1-3-2", "label": "a1-3-2", "depth": "3"},
		{"value": "a1-3-3", "label": "a1-3-3", "depth": "3"},
		{"value": "a1-4", "label": "a1-4", "depth": "2"},
